/* ---------- Decision prompt ---------- */
/* the agent asks in the chat: no container; with .panel it becomes a card */
.dpx{padding:16px 0;display:flex;flex-direction:column;gap:12px;outline:0;border-radius:var(--r-in)}
.dpx.panel{padding:16px;border-radius:var(--r-card)}
.dpx:focus-visible{outline:2px solid color-mix(in srgb,var(--accent-mark,var(--accent)) 45%,transparent);outline-offset:6px}
.dpx-h{display:flex;align-items:center;justify-content:space-between}
.dpx-k{font-size:12px}
.dpx-dots{display:flex;gap:4px}
.dpx-dots i{width:6px;height:6px;border-radius:3px;background:var(--line);transition:width .45s var(--ease),background .35s}
.dpx-dots i.on{width:16px;background:var(--accent-mark,var(--accent))}
.dpx-dots i.done{background:var(--accent-mark,var(--accent));opacity:.4}
.dpx-body{min-height:168px}
.dpx-q{font-size:14px;font-weight:500;margin-bottom:10px;text-wrap:balance}
.dpx-o{display:flex;align-items:center;gap:10px;width:calc(100% + 20px);margin-inline:-10px;padding:9px 10px;border-radius:12px;font-size:13.5px;text-align:left;color:var(--fg2);transition:background .25s,color .25s}
@media (hover:hover) and (pointer:fine){.dpx-o:hover{background:var(--row);color:var(--fg)}}
.dpx-o.on{background:var(--sel);color:var(--fg)}
.dpx-o .kbd{width:20px;text-align:center;transition:background .25s,color .25s}
.dpx-o.on .kbd{background:var(--accent);color:var(--on-accent)}
.dpx-o .d{margin-left:auto;font-size:12px;color:var(--muted)}
.dpx-f{display:flex;justify-content:flex-end;gap:6px}
.dpx-sum{display:flex;flex-direction:column;gap:6px}
.dpx-sr{display:flex;gap:10px;font-size:13px;padding:7px 0;border-bottom:1px solid var(--line)}
.dpx-sr:last-child{border:0}
.dpx-sr span{color:var(--muted);width:92px;flex:none}
.dpx-run{display:flex;align-items:center;gap:8px;font-size:13px;margin-top:6px}

DM.def('decision-prompt', (r, c) => {
  const Q = [
    ['Which frames should the agent redesign?', 'Frames', [['Pricing only','1 frame'],['Pricing and checkout','3 frames'],['The whole flow','9 frames']]],
    ['How bold can the changes be?', 'Scope', [['Polish spacing and type','Safe'],['Rework the layout','Medium'],['Fresh direction','Bold']]],
    ['Where should the result go?', 'Output', [['New Figma page','Keeps the original'],['Branch in the repo','Opens a PR'],['Both','Recommended']]]
  ];
  const ans = []; let qi = 0, sel = 0, done = false;
  const body = $('.dpx-body', r), k = $('.dpx-k', r), dots = $$('.dpx-dots i', r), go = $('.dpx-go', r), skip = $('.dpx-skip', r), card = $('.dpx', r);
  function paint(){
    k.textContent = 'Question ' + (qi + 1) + ' of 3';
    dots.forEach((d, i) => { d.classList.toggle('on', i === qi); d.classList.toggle('done', i < qi); });
    const q = Q[qi];
    body.innerHTML = `<div class="dpx-q">${q[0]}</div>` + q[2].map((o, i) => `<button class="dpx-o${i === sel ? ' on' : ''}" data-i="${i}"><span class="kbd">${i + 1}</span>${o[0]}<span class="d">${o[1]}</span></button>`).join('');
    enter($('.dpx-q', body)); stagger($$('.dpx-o', body), 50, 60);
    $$('.dpx-o', body).forEach(b => { b.onclick = () => choose(+b.dataset.i); b.ondblclick = next; });
  }
  function choose(i){ sel = i; $$('.dpx-o', body).forEach((b, j) => b.classList.toggle('on', j === i)); }
  function next(skipped){
    if (done) return; ans.push(skipped === true ? 'Agent decides' : Q[qi][2][sel][0]); qi++; sel = 0;
    if (qi < Q.length) return paint();
    done = true; dots.forEach(d => { d.classList.remove('on'); d.classList.add('done'); }); k.textContent = 'All set';
    go.parentElement.classList.add('leave');
    body.innerHTML = `<div class="dpx-sum">${Q.map((q, i) => `<div class="dpx-sr"><span>${q[1]}</span>${ans[i]}</div>`).join('')}<div class="dpx-run"><span class="think on"><i></i><i></i><i></i><i></i></span><span class="shim">Starting the redesign</span></div></div>`;
    stagger($$('.dpx-sr, .dpx-run', body), 70);
  }
  go.onclick = () => next(); skip.onclick = () => next(true);
  c.on(card, 'keydown', e => { if (done) return; if (/^[1-3]$/.test(e.key)){ choose(+e.key - 1); e.preventDefault(); } else if (e.key === 'Enter'){ next(); e.preventDefault(); } else if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ choose((sel + (e.key === 'ArrowDown' ? 1 : 2)) % 3); e.preventDefault(); } });
  paint();
});
